select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"open_library_id":"OL28641A"},"seq":1,"relation":"authors","after_row":{"id":987328001,"name":"Robert A. Heinlein","open_library_id":"OL28641A"},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL59705W"},"seq":2,"relation":"works","after_row":{"id":987128001,"title":"The Number of the Beast","cover_id":14372633,"author_id":987328001,"work_type":"novel","source_type":"open_library","open_library_id":"OL59705W","first_publish_year":1980,"native_identity_key":"nlscale:20261102:ol:OL59705W"},"before_row":null},{"key":{"open_library_edition_id":"OL48596241M"},"seq":3,"relation":"editions","after_row":{"id":987228001,"title":"Het getal van het beest","isbn_10":null,"isbn_13":"9789061202509","work_id":987128001,"cover_id":14372633,"language":"dut","publisher":"Elmar Science Fiction","publish_date":null,"open_library_edition_id":"OL48596241M"},"before_row":null},{"key":{"work_id":987128001,"language":"nl"},"seq":4,"relation":"catalog_work_descriptions","after_row":{"text":"Zeb, Deety, Hilda en Jake worden aangevallen door buitenaardse tegenstanders en weten ternauwernood te ontsnappen. Hun voertuig, de Gay Deceiver, is meer dan een gewoon vervoermiddel: het kan verschillende bestaansniveaus doorkruisen. De vlucht voert het gezelschap daardoor naar parallelle werelden, waar de vertrouwde werkelijkheid geen vaste maatstaf meer biedt. Heinlein gebruikt de reis om uiteenlopende mogelijkheden van een universum naast elkaar te zetten. De vier proberen hun weg te vinden terwijl ze aan het gevaar willen ontkomen.","work_id":987128001,"evidence":[{"note":"Full published1980NumberOfTheBeast, not1977parallelmanuscript/PursuitPankera2020 or1979serialexcerpt. DutchElmarpaperback9789061202509 and532p agree with exactKB and physicalDeSlegte; editionprinting1981/1982 differs, no fabricatedexactprintdate. RobertAnsonHeinlein is primary, BobvanLaerhoven translator not coauthor.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p821084968"],"reference":"new-work-dossier-readings-029.json#69","checked_at":"2026-11-02T22:48:16.876Z"},{"type":"original_substantive_source_review","review":"content-amendment-012.json","sources":["https://www.arcmanorbooks.com/product-page/the-number-of-the-beast-reprint","https://www.heinleinarchive.org/product-page/opus-179b-number-of-the-beast","https://www.deslegte.com/het-getal-van-het-beest-376830/","https://openlibrary.org/works/OL59705W","https://data.bibliotheken.nl/id/nbt/p821084968"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"8a34c5bdea667fba3763a269d87c073dec950df5ce317da1775f15f2faa0820f","cover_id":14372633,"reference":"cover-semantic-review-012.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.arcmanorbooks.com/product-page/the-number-of-the-beast-reprint","reviewed_at":"2026-11-02T22:48:16.876+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-029","review_status":"approved","bound_author_id":987328001},"before_row":null},{"key":{"edition_id":987228001},"seq":5,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987128001,"evidence":[{"note":"Full published1980NumberOfTheBeast, not1977parallelmanuscript/PursuitPankera2020 or1979serialexcerpt. DutchElmarpaperback9789061202509 and532p agree with exactKB and physicalDeSlegte; editionprinting1981/1982 differs, no fabricatedexactprintdate. RobertAnsonHeinlein is primary, BobvanLaerhoven translator not coauthor.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p821084968"],"reference":"new-work-dossier-readings-029.json#69","checked_at":"2026-11-02T22:48:16.876Z"},{"type":"original_substantive_source_review","review":"content-amendment-012.json","sources":["https://www.arcmanorbooks.com/product-page/the-number-of-the-beast-reprint","https://www.heinleinarchive.org/product-page/opus-179b-number-of-the-beast","https://www.deslegte.com/het-getal-van-het-beest-376830/","https://openlibrary.org/works/OL59705W","https://data.bibliotheken.nl/id/nbt/p821084968"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"8a34c5bdea667fba3763a269d87c073dec950df5ce317da1775f15f2faa0820f","cover_id":14372633,"reference":"cover-semantic-review-012.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"cover_url":"https://covers.openlibrary.org/b/id/14372633-L.jpg?default=false","edition_id":987228001,"bound_title":"Het getal van het beest","reviewed_at":"2026-11-02T22:48:16.876+00:00","bound_isbn13":"9789061202509","evidence_url":"https://data.bibliotheken.nl/id/nbt/p821084968","review_batch":"nl-scale-20261102-029","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/14372633-M.jpg?default=false","bound_author_id":987328001},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL267619W"},"seq":6,"relation":"works","after_row":{"id":987128002,"title":"Astérix en Corse","cover_id":13137507,"author_id":987303005,"work_type":null,"source_type":"open_library","open_library_id":"OL267619W","first_publish_year":1973,"native_identity_key":"nlscale:20261102:ol:OL267619W"},"before_row":null},{"key":{"open_library_edition_id":"OL12802739M"},"seq":7,"relation":"editions","after_row":{"id":987228002,"title":"Asterix op Corsica","isbn_10":null,"isbn_13":"9789032004767","work_id":987128002,"cover_id":13137507,"language":"dut","publisher":"Dargaud Benelux/Oberon","publish_date":null,"open_library_edition_id":"OL12802739M"},"before_row":null},{"key":{"work_id":987128002,"language":"nl"},"seq":8,"relation":"catalog_work_descriptions","after_row":{"text":"Asterix en Obelix reizen naar Corsica, waar een plaatselijk stamhoofd hun hulp nodig heeft tegen de Romeinse machthebbers. Het eiland kent eigen gewoonten, sterke familiebanden en langdurige vetes. Terwijl verzetsstrijders zich in het dichte struikgewas schuilhouden, proberen de Romeinen hun gezag te behouden. De twee Galliërs moeten hun weg vinden tussen die tegenstellingen. Goscinny schreef het verhaal en Uderzo tekende het avontuur, waarin de strijd tegen de bezetter samengaat met botsingen tussen verschillende manieren van leven.","work_id":987128002,"evidence":[{"note":"ExactDutch48p paperback9789032004767 is singleAsterixEnCorse#20, not4-albumomnibus9789032030469. PrimaryscriptRenéGoscinny/artAlbertUderzo confirmed independently; do not create combinedperson or treatartist as different Workauthor. PublishercurrentEnglish2014ebook is contentproof only; Dutch1980/1981printing dates remain distinct from original1973. No automatic tasteeligibility.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p045617724","https://data.bibliotheken.nl/id/nbt/p842428593"],"reference":"new-work-dossier-readings-029.json#98","checked_at":"2026-11-02T22:48:16.876Z"},{"type":"original_substantive_source_review","review":"content-amendment-010.json","sources":["https://www.hachette.co.uk/titles/ren%C3%A9-goscinny-2/asterix-asterix-in-corsica/9781444013276/","https://www.boekenwebsite.nl/boeken/stripboeken/asterix-en-obelix/asterix-op-corsica","https://www.bol.com/nl/nl/p/op-corsica/1001004005093672/","https://comics.lib.msu.edu/rri/arri/asterixb.htm","https://openlibrary.org/works/OL267619W","https://data.bibliotheken.nl/id/nbt/p045617724","https://data.bibliotheken.nl/id/nbt/p842